"""Wrapper transform for DSLs whose launch site is a bare call to a marker
global (CuTeDSL, FlyDSL), unlike Triton's ``kernel[grid](...)``."""

import ast
import os

from aot_tensor.constants import DEFAULT_OP_NAMESPACE_PREFIX
from aot_tensor.transform.wrapper_codegen_utils import strip_jit_unused_decorator

# Leading newline separates it from the wrapper's import header.
_SO_LOADING_TMPL = """
# Auto-generated by triton_aot.kernel_wrapper_codegen
import torch
torch.ops.load_library("{so_path}")
"""


class MarkerCallTransform(ast.NodeTransformer):
    """Rewrites ``marker(...)`` to ``torch.ops.aot_tensor.{op_name}(...)`` and
    emits the ``.so`` load. Subclasses supply where the built ``.so`` lives
    (``kernel_dir``)."""

    def __init__(self, op_name: str, global_names: set[str]) -> None:
        super().__init__()
        self._op_name = op_name
        self._global_names: set[str] = global_names

    def kernel_dir(self) -> str:
        raise NotImplementedError

    def _is_marker_call(self, node: ast.AST) -> bool:
        return (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id in self._global_names
        )

    def visit_FunctionDef(self, node: ast.FunctionDef) -> ast.FunctionDef:
        # Strip @torch.jit.unused: the rewritten body becomes a runnable torch.ops call.
        strip_jit_unused_decorator(node, self._calls_kernel)
        self.generic_visit(node)
        return node

    def _calls_kernel(self, node: ast.FunctionDef) -> bool:
        # Only this function's own body: a call in a nested def is handled when
        # that def is visited, so the outer @torch.jit.unused stays.
        stack: list[ast.AST] = list(node.body)
        while stack:
            child = stack.pop()
            if self._is_marker_call(child):
                return True
            if isinstance(
                child,
                (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef),
            ):
                continue
            stack.extend(ast.iter_child_nodes(child))
        return False

    def visit_Call(self, node: ast.Call) -> ast.expr:
        self.generic_visit(node)
        if not self._is_marker_call(node):
            return node
        ops = ast.Attribute(
            value=ast.Name(id="torch", ctx=ast.Load()), attr="ops", ctx=ast.Load()
        )
        namespace = ast.Attribute(
            value=ops, attr=DEFAULT_OP_NAMESPACE_PREFIX, ctx=ast.Load()
        )
        return ast.Call(
            func=ast.Attribute(value=namespace, attr=self._op_name, ctx=ast.Load()),
            args=node.args,
            keywords=node.keywords,
        )

    def contains_kernel_call(self, node: ast.AST) -> bool:
        # Whole tree, nested scopes included: decides whether to emit the .so load.
        return any(self._is_marker_call(child) for child in ast.walk(node))

    def generate_so_loading_code(self, node: ast.AST, abs_triton_aot_path: str) -> str:
        if not self.contains_kernel_call(node):
            return ""
        so_path = os.path.join(
            abs_triton_aot_path, self.kernel_dir(), f"{self._op_name.lstrip('_')}.so"
        )
        return _SO_LOADING_TMPL.format(so_path=so_path)
